SELECT CAST(COUNT(DISTINCT CASE WHEN PA.strength > 80 AND PA.stamina > 80 THEN PA.player_api_id END) AS REAL) * 100.0 / COUNT(DISTINCT PA.player_api_id) AS percentage
FROM Player_Attributes PA
JOIN Player P ON PA.player_api_id = P.player_api_id;

SELECT COUNT(CASE WHEN p.height < 180 AND pa.overall_rating > 70 THEN 1 END) * 100.0 / COUNT(pa.id) AS percentage
FROM Player p
INNER JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id;

SELECT SUM(CASE WHEN status = 'C' THEN amount ELSE 0 END) * 100.0 / SUM(amount) AS percentage
FROM loan
WHERE amount < 100000;

SELECT expense_description
FROM expense
WHERE cost = (SELECT MAX(cost) FROM expense);

SELECT phone
FROM member
WHERE first_name = 'Carlo' AND last_name = 'Jacobs';

SELECT SUM(cost) AS total_pizza_cost
FROM expense
WHERE expense_description = 'Pizza';

SELECT COUNT(DISTINCT city) AS num_cities
