FROM member m
JOIN major mj ON m.link_to_major = mj.major_id;

SELECT SUM(CASE WHEN b.remaining < 0 THEN 1 ELSE 0 END) * 100.0 / COUNT(e.event_id) AS percentage
FROM event e
