SELECT
  (SELECT SUM(s1.weight_kg) FROM superhero s1 WHERE s1.full_name = 'Emil Blonsky') -
  (SELECT SUM(s2.weight_kg) FROM superhero s2 WHERE s2.full_name = 'Charles Chandler') AS weight_difference;

SELECT 100.0 * SUM(CASE WHEN c.colour = 'Blue' THEN 1 ELSE 0 END) / COUNT(s.superhero_name) AS percentage
FROM superhero s
LEFT JOIN colour c ON c.id = s.eye_colour_id;

SELECT CAST(SUM(CASE WHEN g.gender = 'Male' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN g.gender = 'Female' THEN 1 ELSE 0 END) AS ratio
FROM superhero s
JOIN gender g ON s.gender_id = g.id;

SELECT superhero_name
FROM superhero
WHERE height_cm = (SELECT MAX(height_cm) FROM superhero);

SELECT full_name
FROM superhero
WHERE weight_kg = 0 OR weight_kg IS NULL;

