SELECT SUM(CASE WHEN STRFTIME('%Y', Birthday) > '1930' THEN 1 ELSE 0 END) * 100.0 / COUNT(ID) AS percentage
FROM Patient
WHERE SEX = 'F';

SELECT SUM(CASE WHEN Admission = '+' THEN 1 ELSE 0 END) * 1.0 / SUM(CASE WHEN Admission = '-' THEN 1 ELSE 0 END) AS ratio
FROM Patient
WHERE Diagnosis = 'SLE';

SELECT SUM(CASE WHEN P.Birthday = '1959-02-18' AND L.Date LIKE '1981-11-%' THEN L.`T-CHO` ELSE 0 END) - SUM(CASE WHEN P.Birthday = '1959-02-18' AND L.Date LIKE '1981-12-%' THEN L.`T-CHO` ELSE 0 END) AS decrease_rate
FROM Patient AS P
JOIN Laboratory AS L ON L.ID = P.ID;

SELECT SUM(CASE WHEN UA <= 6.5 THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS percentage
FROM Laboratory
WHERE `U-PRO` > 0 AND `U-PRO` < 30;

SELECT SUM(CASE WHEN Diagnosis = 'BEHCET' THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS percentage
FROM Patient
WHERE SEX = 'M' AND YEAR(`First Date`) = '1981';

SELECT p.Description AS first_documented, p.Diagnosis AS disease
FROM Patient p
WHERE p.ID = 48473;

SELECT COUNT(DISTINCT p.ID)
FROM Patient p
WHERE p.SEX = 'F' AND p.Diagnosis = 'APS';

SELECT SUM(DIAGNOSIS LIKE '%ITP%') * 100.0 / SUM(DIAGNOSIS LIKE '%SLE%') AS proportion
FROM Examination
WHERE SYMPTOMS LIKE '%thrombocytopenia%';

SELECT ROUND(100.0 * SUM(CASE WHEN bond_type = '=' THEN 1 ELSE 0 END) / COUNT(bond_id), 5) AS percentage
FROM bond
WHERE molecule_id = 'TR008';

SELECT COUNT(DISTINCT b.molecule_id) AS num_molecules
FROM bond b
WHERE b.bond_type = '#';

SELECT label
FROM molecule
WHERE molecule_id IN ('TR000', 'TR001', 'TR002');

SELECT DISTINCT b.molecule_id
FROM bond b
WHERE b.bond_type = ' = ';

SELECT 100.0 * COUNT(DISTINCT CASE WHEN b.bond_type = '#' THEN m.molecule_id END) / COUNT(DISTINCT m.molecule_id) AS percent_triple_bond
FROM molecule m
LEFT JOIN bond b ON b.molecule_id = m.molecule_id;

SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM molecule m
    WHERE m.molecule_id = 'TR124'
      AND m.label = '+'
) THEN 'Yes' ELSE 'No' END AS is_carcinogenic;

SELECT atom_id
FROM atom
WHERE molecule_id = 'TR186';

SELECT bond_type
FROM bond
WHERE bond_id = 'TR007_4_19';

SELECT
  (SELECT COUNT(*) FROM bond WHERE molecule_id = 'TR006' AND bond_type = ' = ') AS num_double_bonds,
  (SELECT label FROM molecule WHERE molecule_id = 'TR006') AS carcinogenic;

SELECT CASE WHEN label = '+' THEN 'carcinogenic' ELSE 'non-carcinogenic' END AS carcinogenic_status
FROM molecule
WHERE molecule_id = 'TR000';

